'use client';

import React, { useEffect, useState } from 'react';
import { fetchLiveFixtures, useMockData } from '@/shared/api/sportmonks';
import MatchCard from '@/shared/ui/MatchCard/MatchCard';
import './FixturesList.css';

// Функция для создания тестовых данных (используется при ошибке API)
const getMockLiveFixtures = (): FixtureData[] => {
  const now = new Date();
  const dateStr = now.toISOString();

  return [
    {
      id: 19101,
      starting_at: {
        date_time: dateStr
      },
      participants: {
        data: [
          { id: 501, name: 'Барселона' },
          { id: 502, name: 'Реал Мадрид' }
        ]
      },
      league: {
        data: {
          name: 'Ла Лига'
        }
      },
      scores: {
        data: {
          score: [
            { participant: 'home', goals: 2 },
            { participant: 'away', goals: 1 }
          ]
        }
      }
    },
    {
      id: 19102,
      starting_at: {
        date_time: dateStr
      },
      participants: {
        data: [
          { id: 503, name: 'Манчестер Юнайтед' },
          { id: 504, name: 'Ливерпуль' }
        ]
      },
      league: {
        data: {
          name: 'Премьер-лига'
        }
      },
      scores: {
        data: {
          score: [
            { participant: 'home', goals: 0 },
            { participant: 'away', goals: 2 }
          ]
        }
      }
    },
    {
      id: 19103,
      starting_at: {
        date_time: dateStr
      },
      participants: {
        data: [
          { id: 505, name: 'Бавария' },
          { id: 506, name: 'Боруссия Д' }
        ]
      },
      league: {
        data: {
          name: 'Бундеслига'
        }
      },
      scores: {
        data: {
          score: [
            { participant: 'home', goals: 3 },
            { participant: 'away', goals: 2 }
          ]
        }
      }
    }
  ];
};

interface FixtureData {
  id: number;
  starting_at: {
    date_time: string;
  };
  participants: {
    data: {
      id: number;
      name: string;
    }[];
  };
  league: {
    data: {
      name: string;
    };
  };
  scores?: {
    data: {
      score: {
        participant: string;
        goals: number;
      }[];
    };
  };
}

// Функция для получения live-матчей через прямой эндпоинт (если доступен)
const fetchLiveFixturesDirect = async () => {
  try {
    const timezone = localStorage.getItem('userTimezone') || 'auto';
    const response = await fetch(`/api/sportmonks/live?timezone=${timezone}`);

    if (!response.ok) {
      throw new Error(`Ошибка при запросе: ${response.status} ${response.statusText}`);
    }

    return await response.json();
  } catch (error) {
    console.error('Ошибка при прямом запросе live-матчей:', error);
    // Возвращаем пустые данные при ошибке
    return { data: [] };
  }
};

const LiveFixtures: React.FC = () => {
  const [fixtures, setFixtures] = useState<FixtureData[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [useMock, setUseMock] = useState<boolean>(useMockData());
  const [dataSource, setDataSource] = useState<string>('loading');

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);

      // Если включен режим моковых данных, используем их
      if (useMock) {
        console.log('Используем тестовые данные для разработки...');
        setFixtures(getMockLiveFixtures());
        setDataSource('mock');
        setIsLoading(false);
        return;
      }

      try {
        console.log('Запрашиваем live-матчи...');

        // Сначала пробуем использовать прямой эндпоинт
        let response;
        try {
          response = await fetchLiveFixturesDirect();
          console.log('Получены данные через прямой эндпоинт');
          setDataSource('direct');
        } catch (directError) {
          // Если прямой эндпоинт недоступен, используем общий метод
          console.log('Прямой эндпоинт недоступен, используем общий метод...');
          response = await fetchLiveFixtures();
          setDataSource('proxy');
        }

        console.log('Полученные данные:', response);

        // Детальное логирование
        if (response.data && Array.isArray(response.data)) {
          console.log(`Найдено ${response.data.length} live-матчей`);
          if (response.data.length > 0) {
            const firstMatch = response.data[0];
            console.log('Пример матча:', {
              id: firstMatch.id,
              name: firstMatch.name,
              starting_at: firstMatch.starting_at,
              teams: firstMatch.participants?.data?.map((team: any) => team.name) || [],
              league: firstMatch.league?.data?.name || 'Неизвестная лига',
              scores: firstMatch.scores || []
            });
          }
        }

        setFixtures(response.data || []);
      } catch (err) {
        console.error('Ошибка при загрузке live-матчей:', err);
        setError(err instanceof Error ? err.message : 'Неизвестная ошибка');

        // В случае ошибки используем тестовые данные
        console.log('Произошла ошибка запроса, используем тестовые данные...');
        setFixtures(getMockLiveFixtures());
        setDataSource('mock-fallback');
        setError('Данные предоставлены для демонстрации (ошибка API)');
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();

    // Обновляем данные каждые 60 секунд (только если не используем мок)
    let interval: NodeJS.Timeout | null = null;
    if (!useMock) {
      interval = setInterval(fetchData, 60000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [useMock]);

  // Конвертация данных API в формат наших компонентов
  const mapFixturesToMatches = (fixtures: FixtureData[]) => {
    return fixtures.map(fixture => {
      // Получаем команды
      const homeTeam = fixture.participants.data?.[0]?.name || 'Неизвестно';
      const awayTeam = fixture.participants.data?.[1]?.name || 'Неизвестно';

      // Получаем счет, если доступен
      let homeScore = 0;
      let awayScore = 0;
      if (fixture.scores?.data) {
        homeScore = fixture.scores.data.score.find(s => s.participant === 'home')?.goals || 0;
        awayScore = fixture.scores.data.score.find(s => s.participant === 'away')?.goals || 0;
      }

      // Форматируем время из API (даты приходят уже в запрошенном часовом поясе)
      const dateObj = new Date(fixture.starting_at.date_time);
      const formattedDate = dateObj.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' });

      return {
        id: fixture.id.toString(),
        home: homeTeam,
        away: awayTeam,
        status: 'LIVE' as const,
        homeScore,
        awayScore,
        date: formattedDate,
        tournament: fixture.league.data?.name
      };
    });
  };

  const matchesData = mapFixturesToMatches(fixtures);

  if (isLoading && fixtures.length === 0) {
    return <div className="fixtures-loading">Загрузка live-матчей...</div>;
  }

  if (error) {
    return <div className="fixtures-error">❌ Ошибка: {error}</div>;
  }

  return (
    <div className="fixtures-list">
      <div className="live-fixtures-header">
        <h2>🔴 Матчи в прямом эфире</h2>
        <div className="update-info">
          {useMock ? (
            <span className="mock-data-notice">Используются тестовые данные</span>
          ) : dataSource === 'direct' ? (
            <span className="direct-api-notice">Прямое подключение к API</span>
          ) : dataSource === 'proxy' ? (
            <span className="proxy-api-notice">Подключение через прокси</span>
          ) : dataSource === 'mock-fallback' ? (
            <span className="fallback-notice">Тестовые данные (ошибка API)</span>
          ) : (
            <span>Автообновление каждую минуту</span>
          )}
          <button 
            className="toggle-mock-btn" 
            onClick={() => setUseMock(!useMock)}
          >
            {useMock ? 'Использовать реальные данные' : 'Использовать тестовые данные'}
          </button>
        </div>
      </div>

      {matchesData.length > 0 ? (
        <div className="fixtures-grid">
          {matchesData.map(match => (
            <MatchCard
              key={match.id}
              homeTeam={match.home}
              awayTeam={match.away}
              status="LIVE"
              homeScore={match.homeScore}
              awayScore={match.awayScore}
              date={match.date}
              tournament={match.tournament}
            />
          ))}
        </div>
      ) : (
        <div className="fixtures-empty">В данный момент нет матчей в прямом эфире</div>
      )}
    </div>
  );
};

export default LiveFixtures;
